style.css:
@-moz-document domain("youtube.com") {
/* Revert Ambient Glow & Modern Channel Radii */
    html, [theme="dark"], [dark] {
        --yt-spec-brand-background-solid: #0f0f0f !important;
        --yt-spec-general-background-a: #0f0f0f !important;
        --yt-spec-raised-background: #212121 !important;
    }
    
    /* Force 2022 Square Borders on Channel Avatar & Thumbnails */
    ytd-channel-avatar-editor,
    yt-img-shadow,
    #avatar.ytd-channel-name,
    #avatar-container.ytd-channel-renderer,
    .ytd-channel-avatar-renderer-fallback,
    #avatar-inline.ytd-c4-tabbed-header-renderer {
        border-radius: 0% !important;
    }
    
    ytd-thumbnail,
    ytd-thumbnail a,
    .ytp-player-content,
    .ytp-ce-video,
    .ytp-ce-playlist {
        border-radius: 0px !important;
    }

    /* Fix Broken Grid Allocations on Channel Video Tab */
    ytd-browse[page-subtype="channels"] ytd-grid-video-renderer {
        margin-right: 4px !important;
        margin-bottom: 24px !important;
    }

    /* Restore Sharp Channel Action Buttons */
    yt-button-shape,
    .yt-spec-button-shape-next--size-m {
        border-radius: 2px !important;
    }
    
    /* Strip away annoying bottom padding added in 2024 layouts */
    #page-manager.ytd-app {
        --ytd-rich-grid-items-per-row: 4 !important;
    }
}
